import datetime

def next_business_day(date_str: str, holidays: list[str]) -> str:
    """Return the first business day after `date_str`, skipping weekends and holidays."""
    start = datetime.date.fromisoformat(date_str)
    holiday_set = {datetime.date.fromisoformat(h) for h in holidays}
    current = start
    while True:
        current += datetime.timedelta(days=1)
        if current.weekday() < 5 and current not in holiday_set:
            return current.isoformat()
