def parse_csv_line(line: str) -> list[str]:
    if line == "":
        return [""]
    fields: list[str] = []
    i, n = 0, len(line)
    while i < n:
        if line[i] == ",":
            fields.append("")
            i += 1
            continue
        if line[i] == '"':
            i += 1
            value_chars: list[str] = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        value_chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    value_chars.append(line[i])
                    i += 1
            fields.append("".join(value_chars))
            if i < n and line[i] == ",":
                i += 1
            continue
        start = i
        while i < n and line[i] != ",":
            i += 1
        fields.append(line[start:i])
        if i < n and line[i] == ",":
            i += 1
    if line and line[-1] == ",":
        fields.append("")
    return fields
