def flatten(obj: dict, sep: str = ".") -> dict:
    def _flatten(value, prefix):
        if isinstance(value, dict):
            if value:
                res = {}
                for k, v in value.items():
                    new_prefix = f"{prefix}{sep}{k}"
                    res.update(_flatten(v, new_prefix))
                return res
            else:
                return {prefix: {}}
        elif isinstance(value, list):
            if value:
                res = {}
                for idx, v in enumerate(value):
                    new_prefix = f"{prefix}{sep}{idx}"
                    res.update(_flatten(v, new_prefix))
                return res
            else:
                return {prefix: []}
        else:
            return {prefix: value}

    result = {}
    for key, val in obj.items():
        result.update(_flatten(val, key))
    return result
