def is_valid_ipv4(s: str) -> bool:
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not all('0' <= c <= '9' for c in part):
            return False
        if part[0] == '0' and len(part) > 1:
            return False
        try:
            value = int(part)
        except ValueError:
            return False
        if value < 0 or value > 255:
            return False
    return True
