def to_roman(n: int) -> str:
    """Convert an integer (1‑3999) to its minimal Roman numeral."""
    if not isinstance(n, int) or n < 1 or n > 3999:
        raise ValueError("Integer value out of range (1..3999)")

    values = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    parts = []
    for val, sym in values:
        if n >= val:
            q, n = divmod(n, val)
            parts.append(sym * q)
    return "".join(parts)


def from_roman(s: str) -> int:
    """Parse a minimal Roman numeral and return its integer value."""
    if not isinstance(s, str) or not s:
        raise ValueError("Input must be a non‑empty string")

    roman_map = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

    if any(c not in roman_map for c in s):
        raise ValueError("Roman numeral contains invalid characters")

    total = 0
    prev = 0
    for ch in reversed(s):
        val = roman_map[ch]
        if val < prev:
            total -= val
        else:
            total += val
            prev = val

    if total < 1 or total > 3999:
        raise ValueError("Roman numeral value out of range (1..3999)")

    if to_roman(total) != s:
        raise ValueError("Roman numeral is not in canonical form")

    return total
